CREATE OR REPLACE FUNCTION public.normalize_document_counter() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.client_code:='*'; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.normalize_document_counter() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER normalize_invoice_counter BEFORE INSERT ON public.document_counters FOR EACH ROW WHEN (NEW.document_type='invoice') EXECUTE FUNCTION public.normalize_document_counter();
INSERT INTO public.document_counters(tenant_id,client_code,document_type,sequence) SELECT tenant_id,'*','invoice',COALESCE(max(CASE WHEN invoice_number ~ '^[0-9]+/' THEN split_part(invoice_number,'/',1)::bigint ELSE 0 END),0) FROM public.orders GROUP BY tenant_id ON CONFLICT(tenant_id,client_code,document_type) DO UPDATE SET sequence=GREATEST(public.document_counters.sequence,EXCLUDED.sequence);
CREATE OR REPLACE FUNCTION public.suggest_invoice_number(p_client_name text,p_invoice_date date) RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE code text; seq bigint; fmt text; tid uuid:=public.active_tenant_id(); BEGIN IF NOT public.can_access_tenant_module(tid,'orders') THEN RAISE EXCEPTION 'Tidak berizin'; END IF; code:=regexp_replace(upper(p_client_name),'[^A-Z0-9]','','g'); SELECT GREATEST(COALESCE((SELECT sequence FROM public.document_counters WHERE tenant_id=tid AND client_code='*' AND document_type='invoice'),0),COALESCE((SELECT max(split_part(invoice_number,'/',1)::bigint) FROM public.orders WHERE tenant_id=tid AND invoice_number ~ '^[0-9]+/'),0))+1 INTO seq; SELECT COALESCE(doc_numbering->>'invoice','INV/{CLIENT}/{YYYY}/{MM}/{SEQ}') INTO fmt FROM public.tenant_settings WHERE tenant_id=tid; RETURN replace(replace(replace(replace(fmt,'{CLIENT}',code),'{YYYY}',to_char(p_invoice_date,'YYYY')),'{MM}',to_char(p_invoice_date,'MM')),'{SEQ}',seq::text); END $$;
CREATE OR REPLACE FUNCTION public.track_manual_invoice_sequence() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.invoice_number ~ '^[0-9]+/' THEN INSERT INTO public.document_counters(tenant_id,client_code,document_type,sequence) VALUES(NEW.tenant_id,'*','invoice',split_part(NEW.invoice_number,'/',1)::bigint) ON CONFLICT(tenant_id,client_code,document_type) DO UPDATE SET sequence=GREATEST(public.document_counters.sequence,EXCLUDED.sequence); END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.track_manual_invoice_sequence() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER invoice_sequence_sync AFTER INSERT OR UPDATE OF invoice_number ON public.orders FOR EACH ROW EXECUTE FUNCTION public.track_manual_invoice_sequence();